PREFIXES = {
    'Custom data directory requires explicit profile selection: ': 'Нестандартный каталог нужно явно выбрать в списке профилей: ',
    'Relative custom data directory cannot be resolved safely: ': 'Нельзя безопасно определить относительный каталог данных: ',
    'Excluded profile remains outside reset scope: ': 'Исключённый профиль остаётся вне области сброса: ',
    'Close related processes before applying: ': 'Перед применением закройте/остановите связанные процессы: ',
    'Alternative authentication source must be reviewed: ': 'Проверьте дополнительный источник авторизации: ',
    'Custom data directory requires a supported adapter: ': 'Нестандартный каталог требует отдельного адаптера: ',
}

def ru(text):
    if text in TEXT:
        return TEXT[text]
    for old, new in PREFIXES.items():
        if text.startswith(old):
            return new + text[len(old):]
    return text


